import base64,gzip,hashlib,io,json,os,pathlib,stat,tarfile
raw=base64.b64decode('',validate=True)
assert len(raw)==265304 and hashlib.sha256(raw).hexdigest()=='16d21b200f3e871f58ad30d6ea130d342c467963d432a93bf362fed4748998e4'
with gzip.GzipFile(fileobj=io.BytesIO(raw),mode='rb') as stream:
    expanded=stream.read(2*1024*1024+1)
assert len(expanded)<=2*1024*1024
files={}
with tarfile.open(fileobj=io.BytesIO(expanded),mode='r:') as archive:
    for item in archive:
        name=pathlib.PurePosixPath(item.name)
        assert item.isfile() and not name.is_absolute() and '..' not in name.parts and str(name)==item.name
        assert item.name not in files and 0<=item.size<=256*1024 and len(files)<30
        content=archive.extractfile(item).read(256*1024+1)
        assert len(content)==item.size
        files[item.name]=content
assert len(files)==30 and sum(map(len,files.values()))==1025362
manifest_raw=files['frozen-preparation-manifest.json']
assert len(manifest_raw)==5848 and hashlib.sha256(manifest_raw).hexdigest()=='99e5a9e4826fa9175541174695e0cdaa89210f107ee53d2fcd303ba702c0a4ac'
manifest=json.loads(manifest_raw)
assert manifest['schema']=='hepta-r34-frozen-qualification-preparation/v1'
assert set(files)=={'frozen-preparation-manifest.json'}|{r['path'] for r in manifest['files']}
for row in manifest['files']:
    data=files[row['path']]
    assert len(data)==row['bytes'] and hashlib.sha256(data).hexdigest()==row['sha256']
root=pathlib.Path('/home/qian/hepta-runtime-optimization-20261106-r34')
assert os.getuid()==1000 and root.parent.resolve(strict=True)==root.parent
assert not os.path.lexists(root)
root.mkdir(mode=0o700)
installed=[]
for name,data in sorted(files.items()):
    path=root/name
    path.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
    assert path.parent.resolve(strict=True)==path.parent
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'wb') as stream:
        stream.write(data);stream.flush();os.fsync(stream.fileno())
    assert path.read_bytes()==data
    installed.append({'path':name,'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()})
assert all(not os.path.lexists(root/name) for name in ('source','target-build','qualification-01','preparation.json'))
receipt={'schema':'hepta-r34-frozen-package-install/v1','installed':True,'root':str(root),'source_commit':'5d0b180b832e7f2a8120078231e97ef9e702608a','archive_bytes':len(raw),'archive_sha256':hashlib.sha256(raw).hexdigest(),'manifest_sha256':hashlib.sha256(manifest_raw).hexdigest(),'files':installed,'qualification_started':False,'source_created':False,'cache_moved':False,'tests_or_benchmarks_run':False}
receipt_raw=(json.dumps(receipt,indent=2,sort_keys=True)+'\n').encode()
receipt_path=root/'input-upload-receipt-01.json'
with receipt_path.open('xb') as stream:
    stream.write(receipt_raw);stream.flush();os.fsync(stream.fileno())
print(json.dumps({'installed':True,'files':len(installed),'root':str(root),'receipt_bytes':len(receipt_raw),'receipt_sha256':hashlib.sha256(receipt_raw).hexdigest(),'qualification_started':False},sort_keys=True))
